#include <avr/io.h>

/* Everything lives on port B. PB0 to PB4 are free; PB5 is RESET
   until you burn a fuse you cannot easily undo. */

DDRB  |=  (1 << PB1);          /* PB1 = pin 6, the LED on most boards */
PORTB |=  (1 << PB1);
PORTB &= ~(1 << PB1);

DDRB  &= ~(1 << PB2);          /* PB2 = pin 7, input */
PORTB |=  (1 << PB2);          /* internal pull-up */

if (!(PINB & (1 << PB2))) {
}
